package com.tracksphere.interfaces.rest;
import com.tracksphere.application.safety.SafetyService; import com.tracksphere.application.safety.dto.SafetyDtos.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor public class SafetyController { private final SafetyService service; @PostMapping("/geofences") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.CREATED) public GeofenceResponse geofence(@Valid @RequestBody GeofenceRequest r,@AuthenticationPrincipal UUID actor){return service.createGeofence(r,actor);}@GetMapping("/geofences") public List<GeofenceResponse> geofences(){return service.geofences();}@PostMapping("/sos") @ResponseStatus(HttpStatus.CREATED) public SosResponse sos(@Valid @RequestBody SosRequest r,@AuthenticationPrincipal UUID user){return service.createSos(r,user);}@GetMapping("/sos") @PreAuthorize("hasRole('ADMIN')") public List<SosResponse> sos(){return service.sos();}@GetMapping("/notifications") public List<NotificationResponse> notifications(@AuthenticationPrincipal UUID user){return service.notifications(user);}@GetMapping("/audit-logs") @PreAuthorize("hasRole('ADMIN')") public List<AuditResponse> audit(){return service.audit();} }
